    id: 'meteor', name: '煉獄の業火', en: 'INFERNO METEOR', type: 'spell',
    cost: 4, element: 'fire', glyph: '獄', rarity: 'SR',
    text: '相手に1200ダメージ。相手の攻撃力が最も高いユニットを破壊する。',
  },
  grace: {
    id: 'grace', name: '天啓の光', en: 'DIVINE GRACE', type: 'spell',
    cost: 3, element: 'light', glyph: '啓', rarity: 'R',
    text: 'ライフを1200回復し、カードを1枚引く。',
  },
  command: {
    id: 'command', name: '戦陣の号令', en: 'WAR CRY', type: 'spell',
    cost: 3, element: 'earth', glyph: '令', rarity: 'R',
    text: '自分の全ユニットの攻撃力を500アップする。',
  },
  mirage: {
    id: 'mirage', name: '鏡牢ミラージュ', en: 'MIRAGE PRISON', type: 'trap',
    cost: 2, element: 'water', glyph: '鏡', rarity: 'SR',
    text: '相手の攻撃を無効にし、相手に800ダメージを与える。',
  },
  barrier: {
    id: 'barrier', name: '爆裂障壁', en: 'BLAST BARRIER', type: 'trap',
    cost: 2, element: 'fire', glyph: '壁', rarity: 'SR',
    text: '相手の攻撃を無効にし、攻撃ユニットを破壊する。',
  },
}

// Exactly 24 cards: 18 units + 6 spells/traps.
export const DECK_LIST = [
  ['slime', 2],
  ['wolf', 2],
  ['imp', 1],
  ['ninja', 2],
  ['priest', 2],
  ['guardian', 2],
  ['golem', 1],
  ['knight', 2],
  ['raigo', 1],
  ['gigant', 1],
  ['queen', 1],
  ['dragon', 1],
  ['chain', 1],
  ['meteor', 1],
  ['grace', 1],
  ['command', 1],
  ['mirage', 1],
  ['barrier', 1],
]

export const CARD_COUNT = DECK_LIST.reduce((sum, [, n]) => sum + n, 0)

export function cardIds() {
  return DECK_LIST.flatMap(([id, n]) => Array.from({ length: n }, () => id))
}

// Pure-ish duel engine for DUEL 24.
//
// The engine mutates a serialisable state object and returns an event list.
// The UI replays those events as animation cues, which keeps rules and
// presentation separate and makes a network mirror (host -> guest) possible.

import { CARDS, cardIds } from './cards.js'

export const START_LP = 4000
export const HAND_LIMIT = 9
export const MAX_ENERGY = 10
export const ZONES = 6
export const DECK_SIZE = 24

let uidCounter = 0
const nextUid = () => `u${++uidCounter}`

export const other = side => (side === 'p' ? 'c' : 'p')
export const atkOf = card => (card ? card.atk + (card.atkBonus || 0) : 0)
export const defOf = card => (card ? card.def : 0)

export function shuffle(list) {
  const out = list.slice()
  for (let i = out.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[out[i], out[j]] = [out[j], out[i]]
  }
  return out
}

function makeCard(defId, owner) {
  const def = CARDS[defId]
  if (!def) throw new Error(`Unknown card: ${defId}`)
  return {
    uid: nextUid(),
    defId,
    owner,
    name: def.name,
    en: def.en,
    type: def.type,
    cost: def.cost,
    atk: def.atk || 0,
    def: def.def || 0,
    element: def.element,
    glyph: def.glyph,
    rarity: def.rarity,
    text: def.text,
    atkBonus: 0,
    attacked: false,
    faceDown: def.type === 'trap',
    turnSet: 0,
  }
}

function buildDeck(owner) {
  return shuffle(cardIds().map(id => makeCard(id, owner)))
}

function newSide(name) {
  return {
    name,
    lp: START_LP,
    energy: 3,
    maxEnergy: 3,
    turns: 0,
    deck: [],
    hand: [],
    front: Array(ZONES).fill(null),
    back: Array(ZONES).fill(null),
    grave: [],
    damageDealt: 0,
    destroyed: 0,
    played: 0,
  }
}

export function createGame(playerName = 'DUELIST', cpuName = 'CPU DUELIST') {
  const p = newSide(playerName)
  const c = newSide(cpuName)
  p.deck = buildDeck('p')
  c.deck = buildDeck('c')
  // Opening hands.
  for (let i = 0; i < 5; i += 1) {
    p.hand.push(p.deck.pop())
    c.hand.push(c.deck.pop())
  }
  p.turns = 1
  p.maxEnergy = 3
  p.energy = 3
  c.turns = 0
  c.maxEnergy = 3
  c.energy = 3
  return {
    turn: 1,
    turnSide: 'p',
    over: false,
    winner: null,
    p,
    c,
  }
}

function checkWin(state, events) {
  if (state.over) return
  for (const side of ['p', 'c']) {
    if (state[side].lp <= 0) {
      state.over = true
      state.winner = other(side)
      events.push({ type: 'gameover', loser: side, winner: other(side) })
      return
    }
  }
}

function damage(state, side, amount, source, by, events) {
  if (amount <= 0) return
  const target = state[side]
  const before = target.lp
  target.lp = Math.max(0, target.lp - amount)
  if (by && state[by]) state[by].damageDealt += before - target.lp
  events.push({
    type: 'damage', side, amount: before - target.lp, before, after: target.lp, source, by: by || null,
  })
  checkWin(state, events)
}

function heal(state, side, amount, events) {
  const target = state[side]
  const before = target.lp
  target.lp = Math.min(START_LP, target.lp + amount)
  events.push({ type: 'heal', side, amount: target.lp - before, before, after: target.lp })
}

export function drawCards(state, side, count, events) {
  const s = state[side]
  for (let i = 0; i < count; i += 1) {
    if (!s.deck.length) {
      if (s.grave.length) {
        s.deck = shuffle(s.grave.splice(0, s.grave.length))
        events.push({ type: 'shuffle', side })
      }
    }
    if (!s.deck.length) {
      events.push({ type: 'deckout', side, amount: 500 })
      damage(state, side, 500, 'deckout', other(side), events)
      if (state.over) return
      continue
    }
    const card = s.deck.pop()
    if (s.hand.length >= HAND_LIMIT) {
      s.grave.push(card)
      events.push({ type: 'burn', side, card })
    } else {
      s.hand.push(card)
      events.push({ type: 'draw', side, card })
    }
  }
}

export function destroyUnit(state, side, zone, events, reason = 'battle') {
  const s = state[side]
  const card = s.front[zone]
  if (!card) return
  s.front[zone] = null
  s.grave.push(card)
  events.push({ type: 'destroy', side, row: 'front', zone, card, reason })
}

function removeTrap(state, side, zone, events) {
  const s = state[side]
  const card = s.back[zone]
  if (!card) return null
  s.back[zone] = null
  card.faceDown = false
  s.grave.push(card)
  events.push({ type: 'trapUsed', side, zone, card })
  return card
}

function applySpell(state, side, card, events) {
  const foe = other(side)
  const s = state[side]
  switch (card.defId) {
    case 'chain':
      damage(state, foe, 800, 'spell', side, events)
      if (!state.over) drawCards(state, side, 1, events)
      break
    case 'meteor': {
      damage(state, foe, 1200, 'spell', side, events)
      if (!state.over) {
        const units = state[foe].front
          .map((c, zone) => (c ? { c, zone } : null))
          .filter(Boolean)
          .sort((a, b) => atkOf(b.c) - atkOf(a.c))
        if (units.length) destroyUnit(state, foe, units[0].zone, events, 'meteor')
      }
      break
    }
    case 'grace':
      heal(state, side, 1200, events)
      drawCards(state, side, 1, events)
      break
    case 'command': {
      const own = s.front.filter(Boolean)
      if (own.length) {
        for (const unit of own) unit.atkBonus += 500
        events.push({ type: 'buff', side, amount: 500, targets: own.map(u => u.uid) })
      } else {
        events.push({ type: 'whiff', side, card })
      }
      break
    }
    default:
      break
  }
}

export function canPlayCard(state, side, card, zone) {
  if (state.over || state.turnSide !== side) return false
  if (!card || card.cost > state[side].energy) return false
  if (zone < 0 || zone >= ZONES) return false
  if (card.type === 'unit') return !state[side].front[zone]
  return !state[side].back[zone]
}

export function playCard(state, side, uid, zone) {
  const s = state[side]
  if (state.over || state.turnSide !== side) return { ok: false, reason: 'turn' }
  const index = s.hand.findIndex(c => c.uid === uid)
  if (index < 0) return { ok: false, reason: 'hand' }
  const card = s.hand[index]
  if (card.cost > s.energy) return { ok: false, reason: 'energy' }
  const events = []
  if (card.type === 'unit') {
    if (s.front[zone]) return { ok: false, reason: 'zone' }
    s.hand.splice(index, 1)
    s.energy -= card.cost
    s.played += 1
    card.attacked = false
    s.front[zone] = card
    events.push({ type: 'summon', side, card, zone })
  } else if (card.type === 'spell') {
    if (s.back[zone]) return { ok: false, reason: 'zone' }
    s.hand.splice(index, 1)
    s.energy -= card.cost
    s.played += 1
    events.push({ type: 'cast', side, card, zone })
    applySpell(state, side, card, events)
    s.grave.push(card)
    events.push({ type: 'toGrave', side, card, from: 'back', zone })
  } else {
    if (s.back[zone]) return { ok: false, reason: 'zone' }
    s.hand.splice(index, 1)
    s.energy -= card.cost
    s.played += 1
    card.faceDown = true
    card.turnSet = state.turn
    s.back[zone] = card
    events.push({ type: 'set', side, card, zone })
  }
  return { ok: true, events }
}

export function canAttack(state, side, zone) {
  if (state.over || state.turnSide !== side) return false
  const unit = state[side].front[zone]
  return Boolean(unit && !unit.attacked)
}

export function canDirectAttack(state, side) {
  return state[other(side)].front.every(c => !c)
}

export function attack(state, side, fromZone, target) {
  const s = state[side]
  if (state.over || state.turnSide !== side) return { ok: false, reason: 'turn' }
  const attacker = s.front[fromZone]
  if (!attacker) return { ok: false, reason: 'unit' }
  if (attacker.attacked) return { ok: false, reason: 'used' }
  const foeSide = other(side)
  const foe = state[foeSide]

  let targetCard = null
  if (target.kind === 'unit') {
    if (target.side !== foeSide) return { ok: false, reason: 'target' }
    targetCard = foe.front[target.zone]
    if (!targetCard) return { ok: false, reason: 'target' }
  } else if (target.kind === 'player') {
    if (!canDirectAttack(state, side)) return { ok: false, reason: 'blocked' }
  } else {
    return { ok: false, reason: 'target' }
  }

  const events = []
  const atk = atkOf(attacker)
  attacker.attacked = true
  const attackEvent = {
    type: 'attack',
    side,
    fromZone,
    attacker,
    target: targetCard
      ? { kind: 'unit', side: foeSide, zone: target.zone, card: targetCard }
      : { kind: 'player', side: foeSide },
    negated: false,
  }
  events.push(attackEvent)

  // Traps fire before battle. The oldest set trap is consumed.
  const trapIndex = foe.back.findIndex(c => c && c.type === 'trap' && c.faceDown)
  if (trapIndex >= 0) {
    const trap = foe.back[trapIndex]
    attackEvent.negated = true
    events.push({ type: 'trap', side: foeSide, zone: trapIndex, card: trap })
    removeTrap(state, foeSide, trapIndex, events)
    if (trap.defId === 'mirage') {
      damage(state, side, 800, 'trap', foeSide, events)
    } else if (trap.defId === 'barrier') {
      destroyUnit(state, side, fromZone, events, 'trap')
      state[side].destroyed += 1
    }
    return { ok: true, events }
  }

  if (targetCard) {
    const defenderDef = defOf(targetCard)
    events.push({
      type: 'battle', side, fromZone, targetZone: target.zone, atk, def: defenderDef,
    })
    if (atk > defenderDef) {
      destroyUnit(state, foeSide, target.zone, events)
      state[side].destroyed += 1
      damage(state, foeSide, atk - defenderDef, 'battle', side, events)
    } else if (atk === defenderDef) {
      destroyUnit(state, side, fromZone, events)
      destroyUnit(state, foeSide, target.zone, events)
      state[side].destroyed += 1
      state[foeSide].destroyed += 1
    } else {
      destroyUnit(state, side, fromZone, events)
      state[foeSide].destroyed += 1
    }
  } else {
    events.push({ type: 'direct', side, targetSide: foeSide, amount: atk })
    damage(state, foeSide, atk, 'direct', side, events)
  }
  return { ok: true, events }
}

function startTurn(state, side, events) {
  const s = state[side]
  s.turns += 1
  s.maxEnergy = Math.min(MAX_ENERGY, 2 + s.turns)
  s.energy = s.maxEnergy
  for (const unit of s.front) if (unit) unit.attacked = false
  events.push({ type: 'turn', side, number: state.turn })
  drawCards(state, side, 1, events)
}

export function endTurn(state) {
  if (state.over) return { ok: false, reason: 'over' }
  const events = []
  state.turnSide = other(state.turnSide)
  state.turn += 1
  startTurn(state, state.turnSide, events)
  return { ok: true, events }
}

// ---- opponent AI ----------------------------------------------------------

const CENTER_FIRST = [2, 3, 1, 4, 0, 5]

function firstEmptyFront(s) {
  for (const i of CENTER_FIRST) if (!s.front[i]) return i
  return -1
}

function firstEmptyBack(s) {
  for (const i of CENTER_FIRST) if (!s.back[i]) return i
  return -1
}

function handCard(s, defId) {
  return s.hand.find(c => c.defId === defId) || null
}

function bestUnit(s, energy) {
  return s.hand
    .filter(c => c.type === 'unit' && c.cost <= energy)
    .sort((a, b) => (b.cost * 100 + b.atk) - (a.cost * 100 + a.atk))[0] || null
}

function bestAttack(state) {
  const s = state.c
  const foe = state.p
  const ready = s.front
    .map((c, zone) => (c && !c.attacked ? { card: c, zone } : null))
    .filter(Boolean)
    .sort((a, b) => atkOf(b.card) - atkOf(a.card))
  if (!ready.length) return null

  if (canDirectAttack(state, 'c')) {
    const best = ready[0]
    return { zone: best.zone, target: { kind: 'player', side: 'p' } }
  }

  const targets = foe.front
    .map((c, zone) => (c ? { card: c, zone } : null))
    .filter(Boolean)
  let best = null
  for (const attacker of ready) {
    const atk = atkOf(attacker.card)
    for (const target of targets) {
      if (atk > target.card.def) {
        const score = atkOf(target.card) + (atk - target.card.def) + (target.card.cost * 50)
        if (!best || score > best.score) {
          best = {
            score,
            zone: attacker.zone,
            target: { kind: 'unit', side: 'p', zone: target.zone },
          }
        }
      }
    }
  }
  return best ? { zone: best.zone, target: best.target } : null
}

export function cpuNextAction(state) {
  if (state.over || state.turnSide !== 'c') return { type: 'end' }
  const s = state.c
  const foe = state.p
  const frontZone = firstEmptyFront(s)
  const backZone = firstEmptyBack(s)

  // Finish the player when possible.
  if (foe.lp <= 800 && backZone >= 0 && s.energy >= 2) {
    const chain = handCard(s, 'chain')
    if (chain) return { type: 'play', uid: chain.uid, zone: backZone }
  }
  if (foe.lp <= 1200 && backZone >= 0 && s.energy >= 4) {
    const meteor = handCard(s, 'meteor')
    if (meteor) return { type: 'play', uid: meteor.uid, zone: backZone }
  }

  // Develop the board first.
  if (frontZone >= 0) {
    const unit = bestUnit(s, s.energy)
    if (unit) return { type: 'play', uid: unit.uid, zone: frontZone }
  }

  // Then cards that improve the current board.
  if (backZone >= 0) {
    const grace = handCard(s, 'grace')
    if (grace && s.energy >= grace.cost && s.lp <= 1600) {
      return { type: 'play', uid: grace.uid, zone: backZone }
    }
    const command = handCard(s, 'command')
    const ownUnits = s.front.filter(Boolean).length
    if (command && s.energy >= command.cost && ownUnits >= 2) {
      return { type: 'play', uid: command.uid, zone: backZone }
    }
    const trap = s.hand.find(c => c.type === 'trap' && c.cost <= s.energy)
    if (trap && (s.energy >= trap.cost + 1 || !bestUnit(s, s.energy) || s.hand.length > 5)) {
      return { type: 'play', uid: trap.uid, zone: backZone }
    }
  }

  if (backZone >= 0) {
    const chain = handCard(s, 'chain')
    if (chain && s.energy >= chain.cost && (foe.lp <= 2000 || s.energy >= 6)) {
      return { type: 'play', uid: chain.uid, zone: backZone }
    }
    const meteor = handCard(s, 'meteor')
    if (meteor && s.energy >= meteor.cost && (foe.front.some(Boolean) || foe.lp <= 1600)) {
      return { type: 'play', uid: meteor.uid, zone: backZone }
    }
  }

  const hit = bestAttack(state)
  if (hit) return { type: 'attack', zone: hit.zone, target: hit.target }
  return { type: 'end' }
}

export function applyCpuAction(state, action) {
  if (action.type === 'play') return playCard(state, 'c', action.uid, action.zone)
  if (action.type === 'attack') return attack(state, 'c', action.zone, action.target)
  return endTurn(state)
}

// Tiny WebAudio synthesizer: no external assets, works offline.
let ctx = null
let master = null
let enabled = true

export function setSoundEnabled(value) {
  enabled = Boolean(value)
  if (master) master.gain.value = enabled ? 0.5 : 0
}

export function soundEnabled() {
  return enabled
}

function ensure() {
  if (!enabled) return null
  if (!ctx) {
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return null
    try {
      ctx = new AC()
      master = ctx.createGain()
      master.gain.value = 0.5
      master.connect(ctx.destination)
    } catch {
      return null
    }
  }
  if (ctx.state === 'suspended') ctx.resume().catch(() => {})
  return ctx
}

function tone(freq, dur, type = 'sine', gain = 0.15, slide = 0, delay = 0) {
  const audio = ensure()
  if (!audio) return
  const t0 = audio.currentTime + delay
  const osc = audio.createOscillator()
  const amp = audio.createGain()
  osc.type = type
  osc.frequency.setValueAtTime(Math.max(20, freq), t0)
  if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t0 + dur)
  amp.gain.setValueAtTime(0.0001, t0)
  amp.gain.exponentialRampToValueAtTime(gain, t0 + 0.012)
  amp.gain.exponentialRampToValueAtTime(0.0001, t0 + dur)
  osc.connect(amp).connect(master)
  osc.start(t0)
  osc.stop(t0 + dur + 0.02)
}

function noise(dur, gain = 0.12, filter = 1800, delay = 0) {
  const audio = ensure()
  if (!audio) return
  const t0 = audio.currentTime + delay
  const length = Math.max(1, Math.floor(audio.sampleRate * dur))
  const buffer = audio.createBuffer(1, length, audio.sampleRate)
  const data = buffer.getChannelData(0)
  for (let i = 0; i < length; i += 1) data[i] = (Math.random() * 2 - 1) * (1 - i / length)
  const src = audio.createBufferSource()
  src.buffer = buffer
  const bp = audio.createBiquadFilter()
  bp.type = 'bandpass'
  bp.frequency.value = filter
  bp.Q.value = 0.8
  const amp = audio.createGain()
  amp.gain.value = gain
  src.connect(bp).connect(amp).connect(master)
  src.start(t0)
}

const SFX = {
  click: () => tone(660, 0.05, 'square', 0.05),
  draw: () => { noise(0.12, 0.06, 3200); tone(880, 0.1, 'sine', 0.05, 220) },
  summon: () => { tone(140, 0.35, 'sawtooth', 0.12, 160); noise(0.18, 0.1, 700) },
  attack: () => { noise(0.18, 0.13, 1100); tone(320, 0.16, 'sawtooth', 0.08, -180) },
  hit: () => { noise(0.24, 0.18, 240); tone(90, 0.3, 'sine', 0.16, -40) },
  trap: () => { tone(520, 0.2, 'triangle', 0.1, 600); noise(0.2, 0.08, 2200) },
  heal: () => { tone(520, 0.3, 'sine', 0.08, 360); tone(780, 0.35, 'sine', 0.06, 260, 0.08) },
  cast: () => { tone(360, 0.28, 'triangle', 0.1, 480); noise(0.16, 0.05, 2600) },
  turn: () => { tone(220, 0.18, 'sine', 0.07, 180); tone(330, 0.22, 'sine', 0.05, 220, 0.08) },
  win: () => { [523, 659, 784, 1046].forEach((f, i) => tone(f, 0.35, 'triangle', 0.1, 0, i * 0.12)) },
  lose: () => { [392, 330, 262, 196].forEach((f, i) => tone(f, 0.45, 'sine', 0.1, -30, i * 0.14)) },
  join: () => { tone(700, 0.09, 'sine', 0.07, 220); tone(980, 0.12, 'sine', 0.06, 160, 0.08) },
  error: () => tone(140, 0.12, 'square', 0.06, -40),
}

export function sfx(name) {
  if (!enabled) return
  const fn = SFX[name]
  if (fn) {
    try { fn() } catch { /* audio is decorative */ }
  }
}

// Cross-tab room lobby.
//
// The harness has no server, so "online" presence is shared between tabs of the
// same origin with localStorage + BroadcastChannel. Opening the game in a second
// tab really does create a second duelist and updates this room list.

const REGISTRY_KEY = 'duel24.rooms.v3'
const PROFILE_KEY = 'duel24.profile.v3'
const SESSION_KEY = 'duel24.session.v3'
const LOBBY_CHANNEL = 'duel24.lobby.v3'
const STALE_MS = 9000
const BEAT_MS = 1800
const MAX_PLAYERS = 2

const ADJECTIVES = ['NOVA', 'ZERO', 'ASTRA', 'KAI', 'LUMA', 'VOLT', 'NEON', 'RYU', 'ECHO', 'ORBIT']
const SUFFIX = '0123456789ABCDEF'

function randomId(prefix = 'r') {
  const bytes = new Uint8Array(8)
  if (window.crypto?.getRandomValues) window.crypto.getRandomValues(bytes)
  else for (let i = 0; i < bytes.length; i += 1) bytes[i] = Math.floor(Math.random() * 256)
  return `${prefix}_${Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('')}`
}

function randomHandle() {
  const adj = ADJECTIVES[Math.floor(Math.random() * ADJECTIVES.length)]
  const tail = Array.from({ length: 2 }, () => SUFFIX[Math.floor(Math.random() * SUFFIX.length)]).join('')
  return `${adj}-${tail}`
}

function readRegistry() {
  try {
    const parsed = JSON.parse(localStorage.getItem(REGISTRY_KEY) || '{"rooms":[]}')
    return Array.isArray(parsed.rooms) ? parsed.rooms : []
  } catch {
    return []
  }
}

function writeRegistry(rooms) {
  try {
    localStorage.setItem(REGISTRY_KEY, JSON.stringify({ rooms }))
  } catch {
    /* storage can be unavailable in private mode */
  }
}

function loadProfile() {
  try {
    const raw = JSON.parse(localStorage.getItem(PROFILE_KEY) || 'null')
    if (raw && typeof raw.name === 'string' && raw.name) return raw
  } catch { /* ignore */ }
  return null
}

function saveProfile(profile) {
  try { localStorage.setItem(PROFILE_KEY, JSON.stringify(profile)) } catch { /* ignore */ }
}

function loadSession() {
  try {
    return sessionStorage.getItem(SESSION_KEY) || ''
  } catch {
    return ''
  }
}

export class Lobby {
  constructor({ onChange, onToast, onRoomMessage } = {}) {
    this.onChange = onChange || (() => {})
    this.onToast = onToast || (() => {})
    this.onRoomMessage = onRoomMessage || (() => {})
    this.clientId = loadSession() || randomId('d')
    try { sessionStorage.setItem(SESSION_KEY, this.clientId) } catch { /* ignore */ }

    const profile = loadProfile()
    this.name = profile?.name || randomHandle()
    this.wins = profile?.wins || 0
    this.profile = { name: this.name, wins: this.wins }

    this.rooms = []
    this.currentId = ''
    this.channel = null
    this.roomChannel = null
    this.beat = null
  }

  start() {
    try {
      this.channel = new BroadcastChannel(LOBBY_CHANNEL)
      this.channel.onmessage = () => this.refresh()
    } catch { /* BroadcastChannel is optional */ }

    // Always own a room at startup, and always be joined to it.
    const reused = this.findReusableOwnRoom()
    if (reused) {
      this.currentId = reused.id
      this.touchRoom(this.currentId)
    } else {
      this.createRoom({ silent: true })
    }
    this.openRoomChannel()
    this.beat = window.setInterval(() => this.heartbeat(), BEAT_MS)
    window.addEventListener('beforeunload', () => this.detach())
    this.refresh(true)
  }

  findReusableOwnRoom() {
    const now = Date.now()
    return readRegistry().find(room => (
      room.hostId === this.clientId
      && now - room.updatedAt < STALE_MS
      && room.players.some(p => p.id === this.clientId)
    )) || null
  }

  get profileName() {
    return this.name
  }

  get currentRoom() {
    return this.rooms.find(r => r.id === this.currentId) || null
  }

  get winsCount() {
    return this.wins
  }

  recordWin() {
    this.wins += 1
    this.profile.wins = this.wins
    saveProfile(this.profile)
    this.onChange(this.rooms, this.currentId)
  }

  randomizeName() {
    this.name = randomHandle()
    this.profile.name = this.name
    saveProfile(this.profile)
    this.onChange(this.rooms, this.currentId)
  }

  prune(rooms, now = Date.now()) {
    return rooms.filter(room => {
      if (!room || !Array.isArray(room.players)) return false
      if (!room.players.length) return false
      if (now - room.updatedAt > STALE_MS) return false
      if (room.players.length === 1 && room.players[0].id !== this.clientId && now - room.updatedAt > STALE_MS / 2) {
        // Give silent tabs a little room before deleting their room.
        return now - room.updatedAt <= STALE_MS
      }
      return true
    }).map(room => ({
      ...room,
      players: room.players.filter(p => now - (p.seen || room.updatedAt) < STALE_MS),
    })).filter(room => room.players.length)
  }

  refresh(force = false) {
    const now = Date.now()
    const rooms = this.prune(readRegistry(), now)
    rooms.sort((a, b) => {
      if (a.id === this.currentId) return -1
      if (b.id === this.currentId) return 1
      return b.updatedAt - a.updatedAt
    })
    const changed = force
      || rooms.length !== this.rooms.length
      || JSON.stringify(rooms.map(r => [r.id, r.updatedAt, r.players.length, r.status]))
        !== JSON.stringify(this.rooms.map(r => [r.id, r.updatedAt, r.players.length, r.status]))
    this.rooms = rooms
    if (!rooms.find(r => r.id === this.currentId)) {
      // The room vanished (host tab closed): land in a fresh personal room.
      this.createRoom({ silent: true, noRefresh: true })
      return
    }
    if (changed) this.onChange(rooms, this.currentId)
  }

  createRoom({ silent = false, noRefresh = false } = {}) {
    const previous = this.currentId
    const now = Date.now()
    const room = {
      id: randomId('room'),
      name: `${this.name} のルーム`,
      hostId: this.clientId,
      hostName: this.name,
      players: [{ id: this.clientId, name: this.name, seen: now }],
      status: 'CPU DUEL',
      max: MAX_PLAYERS,
      createdAt: now,
      updatedAt: now,
      seed: Math.floor(Math.random() * 1e9),
    }
    let rooms = this.prune(readRegistry(), now)
    if (previous) {
      rooms = rooms.filter(r => r.id !== previous)
    }
    rooms.unshift(room)
    writeRegistry(rooms)
    this.currentId = room.id
    this.openRoomChannel()
    this.broadcastSync()
    if (!silent) this.onToast(`ルーム「${room.name}」を開設しました`, 'join')
    if (!noRefresh) this.refresh(true)
    return room
  }

  joinRoom(roomId) {
    const now = Date.now()
    let rooms = this.prune(readRegistry(), now)
    const target = rooms.find(r => r.id === roomId)
    if (!target) {
      this.onToast('そのルームはもう存在しません', 'error')
      this.refresh(true)
      return false
    }
    if (target.id === this.currentId) {
      this.onToast('すでにこのルームに参加しています', 'info')
      return true
    }
    if (target.players.some(p => p.id === this.clientId)) {
      this.currentId = target.id
      this.openRoomChannel()
      this.refresh(true)
      return true
    }
    if (target.players.length >= (target.max || MAX_PLAYERS)) {
      this.onToast('ルームが満員です（2/2）', 'error')
      return false
    }
    // Leave the previous room.
    const previous = this.currentId
    if (previous) {
      rooms = rooms.filter(room => {
        if (room.id !== previous) return true
        room.players = room.players.filter(p => p.id !== this.clientId)
        return room.players.length > 0
      })
    }
    target.players.push({ id: this.clientId, name: this.name, seen: now })
    target.updatedAt = now
    target.status = target.players.length > 1 ? 'PVP READY' : 'CPU DUEL'
    writeRegistry(rooms)
    this.currentId = target.id
    this.openRoomChannel()
    this.onToast(`「${target.name}」に参加しました`, 'join')
    this.broadcastSync()
    this.refresh(true)
    return true
  }

  leaveRoom() {
    // Always keep the player inside a personal room after leaving.
    this.onToast('自分のルームへ戻りました', 'info')
    return this.createRoom()
  }

  touchRoom(roomId) {
    const now = Date.now()
    const rooms = this.prune(readRegistry(), now)
    const room = rooms.find(r => r.id === roomId)
    if (!room) return
    const player = room.players.find(p => p.id === this.clientId)
    if (!player) return
    player.seen = now
    player.name = this.name
    room.updatedAt = now
    if (room.hostId === this.clientId) room.hostName = this.name
    writeRegistry(rooms)
  }

  setStatus(status) {
    const now = Date.now()
    const rooms = this.prune(readRegistry(), now)
    const room = rooms.find(r => r.id === this.currentId)
    if (!room) return
    room.status = status
    room.updatedAt = now
    writeRegistry(rooms)
    this.broadcastSync()
    this.onChange(this.rooms, this.currentId)
  }

  heartbeat() {
    const now = Date.now()
    let rooms = this.prune(readRegistry(), now)
    let touched = false
    for (const room of rooms) {
      const player = room.players.find(p => p.id === this.clientId)
      if (!player) continue
      player.seen = now
      player.name = this.name
      room.updatedAt = now
      if (room.hostId === this.clientId) room.hostName = this.name
      touched = true
    }
    if (touched) {
      writeRegistry(rooms)
      this.broadcastSync()
    }
    this.refresh()
  }

  detach() {
    if (this.beat) window.clearInterval(this.beat)
    try {
      const rooms = readRegistry()
      const room = rooms.find(r => r.id === this.currentId)
      if (room) {
        room.players = room.players.filter(p => p.id !== this.clientId)
        if (!room.players.length) rooms.splice(rooms.indexOf(room), 1)
        writeRegistry(rooms)
      }
      this.channel?.close()
      this.roomChannel?.close()
    } catch { /* ignore */ }
    this.broadcastSync()
  }

  openRoomChannel() {
    try {
      this.roomChannel?.close()
    } catch { /* ignore */ }
    this.roomChannel = null
    if (!this.currentId) return
    try {
      this.roomChannel = new BroadcastChannel(`duel24.room.${this.currentId}`)
      this.roomChannel.onmessage = event => this.onRoomMessage(event.data, event)
    } catch { /* ignore */ }
  }

  sendRoom(payload) {
    try { this.roomChannel?.postMessage(payload) } catch { /* ignore */ }
  }

  broadcastSync() {
    try { this.channel?.postMessage({ type: 'sync', from: this.clientId, at: Date.now() }) } catch { /* ignore */ }
  }

  // Seconds since this room last reported a heartbeat, rendered as ping.
  pingFor(room) {
    const age = Math.max(0, Date.now() - room.updatedAt)
    return Math.min(4, 1 + Math.floor(age / 2500))
  }
}

/* =========================================================================
   DUEL 24 — 24 ZONE ONLINE CARD DUEL
   ========================================================================= */

:root {
  --bg: #04050d;
  --panel: rgba(9, 14, 31, 0.78);
  --panel-strong: rgba(12, 19, 41, 0.94);
  --line: rgba(112, 196, 255, 0.16);
  --line-bright: rgba(112, 220, 255, 0.42);
  --cyan: #37f4ff;
  --cyan-soft: #9bfbff;
  --blue: #3f8cff;
  --magenta: #ff2e8a;
  --magenta-soft: #ff8fbe;
  --gold: #ffd166;
  --green: #4dffb8;
  --text: #eaf3ff;
  --muted: #8fa3c4;
  --muted-2: #607392;
  --header-h: 58px;
  --radius: 16px;
  --font-jp: "IPAPGothic", "IPA Pゴシック", "Noto Sans JP", "Yu Gothic", "Hiragino Kaku Gothic ProN", "WenQuanYi Zen Hei", sans-serif;
  --font-ui: "Lato", "DejaVu Sans", "Segoe UI", system-ui, sans-serif;
  --font-mono: "DejaVu Sans Mono", "Lato", monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-jp);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

body {
  min-height: 100vh;
  min-height: 100dvh;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% -18%, rgba(44, 102, 255, 0.24), transparent 52%),
    radial-gradient(ellipse at 100% 82%, rgba(255, 46, 138, 0.14), transparent 48%),
    radial-gradient(ellipse at 0% 88%, rgba(20, 255, 214, 0.09), transparent 45%),
    #04050d;
}

button {
  font-family: inherit;
  color: inherit;
  cursor: pointer;
}
button:focus-visible, [tabindex]:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 2px;
}
::selection { background: rgba(55, 244, 255, 0.3); }

#bg {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  opacity: 0.9;
  pointer-events: none;
}

.nebula {
  position: fixed;
  inset: -20%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 24% 30%, rgba(48, 84, 255, 0.20), transparent 26%),
    radial-gradient(circle at 76% 24%, rgba(255, 46, 138, 0.14), transparent 24%),
    radial-gradient(circle at 62% 76%, rgba(24, 255, 209, 0.10), transparent 25%);
  filter: blur(30px);
  animation: nebulaDrift 26s ease-in-out infinite alternate;
}

.vignette {
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(2, 3, 8, 0.48), transparent 18%, transparent 82%, rgba(2, 3, 8, 0.6)),
    radial-gradient(ellipse at center, transparent 38%, rgba(0, 0, 0, 0.58) 100%);
}

/* ------------------------------------------------------------------ header */

.topbar {
  position: relative;
  z-index: 40;
  height: var(--header-h);
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 0 18px;
  padding-top: env(safe-area-inset-top);
  border-bottom: 1px solid rgba(112, 196, 255, 0.12);
  background: linear-gradient(180deg, rgba(4, 7, 18, 0.92), rgba(4, 7, 18, 0.55) 78%, transparent);
}
.topbar::after {
  content: "";
  position: absolute;
  left: 4%;
  right: 4%;
  bottom: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(55, 244, 255, 0.55), rgba(255, 46, 138, 0.4), transparent);
  opacity: 0.65;
}

.brand { display: flex; align-items: center; gap: 10px; flex: none; }
.brand-sigil {
  position: relative;
  width: 38px;
  height: 42px;
  display: grid;
  place-items: center;
  clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%);
  background: linear-gradient(160deg, rgba(55, 244, 255, 0.22), rgba(63, 140, 255, 0.08) 50%, rgba(255, 46, 138, 0.18));
  box-shadow: 0 0 22px rgba(55, 244, 255, 0.28);
}
.brand-sigil::before {
  content: "";
  position: absolute;
  inset: 1px;
  clip-path: inherit;
  background: linear-gradient(160deg, #0a1226, #050813);
  z-index: 0;
}
.brand-sigil::after {
  content: "";
  position: absolute;
  inset: 4px;
  clip-path: inherit;
  border: 1px solid rgba(55, 244, 255, 0.35);
  z-index: 1;
}
.brand-sigil span {
  position: relative;
  z-index: 2;
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 900;
  letter-spacing: -0.04em;
  color: var(--cyan-soft);
  text-shadow: 0 0 10px rgba(55, 244, 255, 0.9);
}
.brand-text { display: flex; flex-direction: column; line-height: 1; }
.brand-title {
  font-family: var(--font-ui);
  font-size: 21px;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-shadow: 0 0 24px rgba(55, 244, 255, 0.35);
}
.brand-accent { color: var(--cyan); margin-left: 2px; }
.brand-sub {
  margin-top: 4px;
  font-family: var(--font-ui);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.42em;
  color: var(--muted);
}

.room-pill {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  max-width: 460px;
  margin: 0 auto;
  padding: 7px 12px;
  border: 1px solid rgba(112, 196, 255, 0.18);
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(14, 24, 52, 0.8), rgba(6, 10, 22, 0.8));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05), 0 8px 30px rgba(0, 0, 0, 0.35);
  font-size: 11px;
  white-space: nowrap;
}
.room-pill-label {
  font-family: var(--font-ui);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: var(--muted-2);
}
.room-pill strong {
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 11px;
  font-weight: 700;
  color: var(--text);
}
.joined-chip {
  flex: none;
  padding: 2px 7px;
  border-radius: 999px;
  background: rgba(77, 255, 184, 0.12);
  border: 1px solid rgba(77, 255, 184, 0.38);
  color: var(--green);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
}
.pulse-dot {
  flex: none;
  position: relative;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 10px var(--green);
}
.pulse-dot::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid rgba(77, 255, 184, 0.5);
  animation: pulseRing 2s ease-out infinite;
}

.top-actions { display: flex; align-items: center; gap: 7px; flex: none; }
.icon-btn {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  border: 1px solid rgba(112, 196, 255, 0.16);
  background: rgba(10, 16, 34, 0.7);
  color: var(--muted);
  transition: color 0.2s, border-color 0.2s, background 0.2s, transform 0.2s;
}
.icon-btn:hover { color: var(--cyan); border-color: rgba(55, 244, 255, 0.5); background: rgba(20, 40, 70, 0.75); transform: translateY(-1px); }
.icon-btn svg { width: 18px; height: 18px; fill: currentColor; }
.icon-btn svg .stroke { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.icon-btn.muted { color: var(--muted-2); opacity: 0.7; }
.icon-btn.muted::after {
  content: "";
  position: absolute;
  width: 18px;
  height: 1px;
  background: var(--magenta);
  transform: rotate(-45deg);
}
.mobile-only { display: none; }

/* ------------------------------------------------------------------ layout */

.layout {
  position: relative;
  z-index: 2;
  height: calc(100dvh - var(--header-h) - env(safe-area-inset-top));
  display: grid;
  grid-template-columns: 268px minmax(0, 1fr) 252px;
  gap: 12px;
  padding: 12px 14px 14px;
  max-width: 1680px;
  margin: 0 auto;
}

.panel {
  position: relative;
  min-height: 0;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(155deg, rgba(20, 31, 62, 0.55), transparent 45%),
    linear-gradient(180deg, rgba(9, 14, 31, 0.9), rgba(5, 8, 18, 0.86));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    0 24px 70px rgba(0, 0, 0, 0.48);
  backdrop-filter: blur(16px);
  clip-path: polygon(0 14px, 14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
}
.panel::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background: linear-gradient(120deg, rgba(55, 244, 255, 0.08), transparent 30%, transparent 70%, rgba(255, 46, 138, 0.06));
}
.panel-head {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 15px 16px 11px;
  border-bottom: 1px solid rgba(112, 196, 255, 0.1);
}
.panel-head h2 {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0;
  font-family: var(--font-ui);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.22em;
  color: var(--muted);
}
.live-dot {
  position: relative;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--magenta);
  box-shadow: 0 0 8px var(--magenta);
}
.live-dot::after { content: ""; position: absolute; inset: -3px; border: 1px solid rgba(255, 46, 138, 0.55); border-radius: 50%; animation: pulseRing 1.8s ease-out infinite; }
.count-chip {
  min-width: 24px;
  padding: 2px 6px;
  border-radius: 6px;
  border: 1px solid rgba(112, 196, 255, 0.24);
  background: rgba(55, 244, 255, 0.08);
  color: var(--cyan-soft);
  font-family: var(--font-ui);
  font-size: 9px;
  font-weight: 800;
  text-align: center;
}

/* ------------------------------------------------------------------ rooms */

.rooms-panel { padding-bottom: 12px; }

.self-card {
  position: relative;
  flex: none;
  margin: 12px 12px 8px;
  padding: 11px 12px 10px;
  border: 1px solid rgba(55, 244, 255, 0.32);
  border-radius: 11px;
  background:
    linear-gradient(135deg, rgba(55, 244, 255, 0.12), transparent 52%),
    linear-gradient(180deg, rgba(12, 24, 47, 0.92), rgba(6, 11, 23, 0.92));
  box-shadow: 0 0 26px rgba(55, 244, 255, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  overflow: hidden;
}
.self-card::after {
  content: "";
  position: absolute;
  top: -50%;
  left: -60%;
  width: 45%;
  height: 200%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.09), transparent);
  transform: rotate(18deg);
  animation: selfSweep 5.5s ease-in-out infinite;
}
.self-top { display: flex; align-items: center; gap: 6px; min-width: 0; }
.you-badge {
  flex: none;
  padding: 1px 5px;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--cyan), #6ea8ff);
  color: #04121c;
  font-family: var(--font-ui);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
}
.self-name {
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.06em;
  color: var(--text);
}
.self-wins { margin-left: auto; font-family: var(--font-ui); font-size: 8px; letter-spacing: 0.08em; color: var(--muted-2); }
.self-wins b { color: var(--gold); font-size: 10px; }
.self-room-name {
  margin-top: 7px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 700;
  color: var(--cyan-soft);
  text-shadow: 0 0 12px rgba(55, 244, 255, 0.3);
}
.self-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 7px;
  font-size: 9px;
  color: var(--muted);
}
.status-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 7px var(--green); }
.self-players { margin-left: auto; font-family: var(--font-ui); font-weight: 700; color: var(--muted); }

.room-list {
  flex: 1;
  min-height: 0;
  margin: 0;
  padding: 2px 12px 8px;
  list-style: none;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: rgba(55, 244, 255, 0.25) transparent;
}
.room-list::-webkit-scrollbar { width: 4px; }
.room-list::-webkit-scrollbar-thumb { background: rgba(55, 244, 255, 0.25); border-radius: 4px; }

.room-item {
  position: relative;
  margin-top: 7px;
  padding: 9px 10px;
  border: 1px solid rgba(112, 196, 255, 0.1);
  border-radius: 9px;
  background: rgba(8, 14, 29, 0.66);
  transition: border-color 0.2s, background 0.2s, transform 0.2s;
  animation: roomIn 0.3s ease both;
}
.room-item:hover { border-color: rgba(55, 244, 255, 0.32); background: rgba(12, 22, 44, 0.8); transform: translateX(2px); }
.room-item.current {
  border-color: rgba(77, 255, 184, 0.38);
  background:
    linear-gradient(90deg, rgba(77, 255, 184, 0.09), transparent 70%),
    rgba(8, 18, 30, 0.82);
}
.room-item.current::before {
  content: "";
  position: absolute;
  left: -1px;
  top: 8px;
  bottom: 8px;
  width: 2px;
  background: var(--green);
  box-shadow: 0 0 10px var(--green);
}
.room-item-top { display: flex; align-items: center; gap: 6px; min-width: 0; }
.room-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10.5px;
  font-weight: 700;
  color: var(--text);
}
.room-flag {
  flex: none;
  margin-left: auto;
  padding: 1px 5px;
  border: 1px solid rgba(77, 255, 184, 0.4);
  border-radius: 4px;
  color: var(--green);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
}
.room-item-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 5px;
  font-family: var(--font-ui);
  font-size: 8px;
  letter-spacing: 0.06em;
  color: var(--muted-2);
}
.room-item-meta .host { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.room-item-bottom { display: flex; align-items: center; gap: 7px; margin-top: 7px; }
.room-status {
  padding: 2px 5px;
  border-radius: 3px;
  background: rgba(55, 244, 255, 0.08);
  color: var(--cyan-soft);
  font-family: var(--font-ui);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.1em;
}
.room-status.pvp { background: rgba(255, 209, 102, 0.12); color: var(--gold); }
.ping { display: flex; align-items: flex-end; gap: 2px; height: 10px; margin-left: auto; }
.ping i { width: 2.5px; border-radius: 1px; background: rgba(77, 255, 184, 0.7); }
.ping i:nth-child(1) { height: 3px; }
.ping i:nth-child(2) { height: 5px; }
.ping i:nth-child(3) { height: 7px; }
.ping i:nth-child(4) { height: 9px; }
.ping i.off { background: rgba(120, 140, 170, 0.25); }
.room-join {
  flex: none;
  padding: 3px 8px;
  border: 1px solid rgba(55, 244, 255, 0.35);
  border-radius: 5px;
  background: rgba(55, 244, 255, 0.08);
  color: var(--cyan-soft);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.06em;
  transition: background 0.2s, color 0.2s;
}
.room-join:hover:not(:disabled) { background: var(--cyan); color: #031018; }
.room-join:disabled { opacity: 0.5; cursor: default; border-color: rgba(77, 255, 184, 0.3); color: var(--green); }
.room-empty {
  padding: 18px 8px;
  text-align: center;
  font-size: 9px;
  line-height: 1.7;
  color: var(--muted-2);
}

.room-tools { flex: none; display: flex; gap: 7px; padding: 9px 12px 0; }
.btn-primary, .btn-ghost {
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
  transition: transform 0.18s, background 0.18s, border-color 0.18s, color 0.18s;
}
.btn-primary {
  flex: 1;
  border: 1px solid rgba(55, 244, 255, 0.55);
  background: linear-gradient(135deg, rgba(55, 244, 255, 0.2), rgba(63, 140, 255, 0.14));
  color: var(--cyan-soft);
  box-shadow: 0 0 18px rgba(55, 244, 255, 0.1);
}
.btn-primary:hover { background: linear-gradient(135deg, var(--cyan), #63a8ff); color: #031018; transform: translateY(-1px); }
.btn-ghost {
  border: 1px solid rgba(112, 196, 255, 0.18);
  background: rgba(10, 16, 32, 0.6);
  color: var(--muted);
}
.btn-ghost:hover { border-color: rgba(255, 46, 138, 0.5); color: var(--magenta-soft); }
.panel-hint {
  flex: none;
  margin: 9px 14px 0;
  font-size: 8.5px;
  line-height: 1.6;
  color: var(--muted-2);
}

/* ------------------------------------------------------------------ arena */

.arena-shell {
  position: relative;
  min-width: 0;
  min-height: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 6px;
  padding: 0 2px;
}
.arena-shell::before {
  content: "";
  position: absolute;
  inset: 4% 6% 8%;
  background: radial-gradient(ellipse at center, rgba(55, 244, 255, 0.08), transparent 65%);
  pointer-events: none;
  filter: blur(18px);
}

.hud {
  position: relative;
  z-index: 3;
  flex: none;
  display: flex;
  align-items: center;
  gap: 11px;
  height: 62px;
  padding: 7px 12px;
  border: 1px solid rgba(112, 196, 255, 0.12);
  border-radius: 13px;
  background:
    linear-gradient(90deg, rgba(20, 31, 62, 0.55), transparent 55%),
    rgba(6, 10, 22, 0.72);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(10px);
  transition: box-shadow 0.3s, border-color 0.3s;
  overflow: hidden;
}
.hud::after {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--cyan);
  opacity: 0.7;
  box-shadow: 0 0 16px var(--cyan);
}
.foe-hud::after { background: var(--magenta); box-shadow: 0 0 16px var(--magenta); }
.foe-hud { border-color: rgba(255, 46, 138, 0.14); }
.hud.active { border-color: rgba(55, 244, 255, 0.4); box-shadow: 0 0 30px rgba(55, 244, 255, 0.1), inset 0 1px 0 rgba(255, 255, 255, 0.05); }
.foe-hud.active { border-color: rgba(255, 46, 138, 0.4); box-shadow: 0 0 30px rgba(255, 46, 138, 0.1), inset 0 1px 0 rgba(255, 255, 255, 0.05); }

.hud-avatar {
  position: relative;
  flex: none;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  clip-path: polygon(50% 0, 93% 25%, 93% 75%, 50% 100%, 7% 75%, 7% 25%);
  background: linear-gradient(160deg, rgba(55, 244, 255, 0.24), rgba(63, 140, 255, 0.08));
}
.hud-avatar::before {
  content: "";
  position: absolute;
  inset: 1px;
  clip-path: inherit;
  background: linear-gradient(160deg, #0a1328, #04070f);
  z-index: 1;
}
.hud-avatar span {
  position: relative;
  z-index: 2;
  font-family: var(--font-ui);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.04em;
  color: var(--cyan-soft);
}
.foe-avatar { background: linear-gradient(160deg, rgba(255, 46, 138, 0.3), rgba(255, 143, 190, 0.07)); }
.foe-avatar span { color: var(--magenta-soft); }
.avatar-ring {
  position: absolute;
  inset: -3px;
  z-index: 0;
  background: conic-gradient(from 0deg, transparent 0 62%, rgba(55, 244, 255, 0.55) 78%, transparent 92%);
  animation: ringSpin 5s linear infinite;
}
.foe-avatar .avatar-ring { background: conic-gradient(from 0deg, transparent 0 62%, rgba(255, 46, 138, 0.55) 78%, transparent 92%); }
.you-hud.active .avatar-ring { animation-duration: 1.6s; }

.hud-main { flex: 1; min-width: 0; }
.hud-topline { display: flex; align-items: center; gap: 7px; margin-bottom: 4px; }
.hud-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--text);
}
.badge {
  flex: none;
  padding: 1px 5px;
  border-radius: 3px;
  font-family: var(--font-ui);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.12em;
}
.badge.you { background: rgba(55, 244, 255, 0.13); border: 1px solid rgba(55, 244, 255, 0.38); color: var(--cyan); }
.badge.foe { background: rgba(255, 46, 138, 0.12); border: 1px solid rgba(255, 46, 138, 0.38); color: var(--magenta-soft); }

.lp-row { display: flex; align-items: center; gap: 9px; }
.lp-track {
  position: relative;
  flex: 1;
  height: 11px;
  border: 1px solid rgba(112, 196, 255, 0.2);
  border-radius: 3px;
  background: rgba(4, 8, 18, 0.85);
  overflow: hidden;
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.7);
}
.lp-fill {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left center;
  background: linear-gradient(90deg, #14d9ff, #6ff8ff 55%, #d8ffff);
  box-shadow: 0 0 14px rgba(55, 244, 255, 0.55);
  transition: width 0.55s cubic-bezier(0.2, 0.8, 0.2, 1), filter 0.3s;
}
.lp-fill.foe { background: linear-gradient(90deg, #ff1e6e, #ff5f9f 55%, #ffb3cf); box-shadow: 0 0 14px rgba(255, 46, 138, 0.55); }
.lp-fill.low { filter: saturate(1.5) hue-rotate(-18deg); animation: lowLp 0.9s ease-in-out infinite; }
.lp-grid {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 calc(10% - 1px), rgba(0, 0, 0, 0.45) calc(10% - 1px) 10%);
  pointer-events: none;
}
.lp-num {
  flex: none;
  min-width: 58px;
  text-align: right;
  font-family: var(--font-mono);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
  color: var(--cyan-soft);
  text-shadow: 0 0 12px rgba(55, 244, 255, 0.4);
}
.foe-hud .lp-num { color: var(--magenta-soft); text-shadow: 0 0 12px rgba(255, 46, 138, 0.4); }
.lp-num.hit { animation: lpHit 0.45s ease; }

.energy-row { display: flex; align-items: center; gap: 6px; margin-top: 4px; }
.energy-label { font-family: var(--font-ui); font-size: 7px; font-weight: 800; letter-spacing: 0.16em; color: var(--muted-2); }
.energy-pips { display: flex; gap: 2.5px; flex: 1; }
.energy-pips i {
  flex: 1;
  max-width: 17px;
  height: 4px;
  border-radius: 2px;
  background: rgba(112, 196, 255, 0.14);
  transition: background 0.2s, box-shadow 0.2s;
}
.energy-pips i.on { background: linear-gradient(90deg, #2fd8ff, #b6fbff); box-shadow: 0 0 7px rgba(55, 244, 255, 0.7); }
.energy-pips i.over { background: rgba(112, 196, 255, 0.28); }
.energy-row b { font-family: var(--font-mono); font-size: 8.5px; letter-spacing: 0.06em; color: var(--muted); }

.hud-meta { flex: none; display: flex; gap: 11px; padding-left: 11px; border-left: 1px solid rgba(112, 196, 255, 0.12); }
.hud-meta div { display: flex; flex-direction: column; align-items: center; gap: 2px; }
.hud-meta span { font-family: var(--font-ui); font-size: 6.5px; font-weight: 800; letter-spacing: 0.14em; color: var(--muted-2); }
.hud-meta b { font-family: var(--font-mono); font-size: 12px; color: var(--text); font-variant-numeric: tabular-nums; }
.you-hud { height: 72px; }

/* board frame */

.board-shell {
  position: relative;
  z-index: 2;
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 2px 0;
}
.board-shell::before {
  content: "";
  position: absolute;
  inset: 6% 3%;
  border-radius: 24px;
  background: radial-gradient(ellipse at center, rgba(55, 244, 255, 0.1), transparent 68%);
  filter: blur(22px);
  pointer-events: none;
}
.board {
  position: relative;
  width: min(100%, calc((100dvh - 355px) * 1.15), 640px);
  aspect-ratio: 1.15;
  max-height: 100%;
  display: grid;
  grid-template-rows: 1fr 1fr 26px 1fr 1fr;
  gap: 5px;
  padding: 9px;
  border: 1px solid rgba(112, 196, 255, 0.24);
  border-radius: 16px;
  background:
    linear-gradient(180deg, rgba(255, 46, 138, 0.05), transparent 18%, transparent 82%, rgba(55, 244, 255, 0.05)),
    linear-gradient(160deg, rgba(13, 23, 48, 0.9), rgba(4, 8, 18, 0.94));
  box-shadow:
    inset 0 0 60px rgba(0, 0, 0, 0.7),
    0 30px 90px rgba(0, 0, 0, 0.6),
    0 0 50px rgba(55, 244, 255, 0.06);
  clip-path: polygon(0 18px, 18px 0, calc(100% - 18px) 0, 100% 18px, 100% calc(100% - 18px), calc(100% - 18px) 100%, 18px 100%, 0 calc(100% - 18px));
}
.board::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(0deg, rgba(55, 244, 255, 0.028) 0 1px, transparent 1px 34px),
    repeating-linear-gradient(90deg, rgba(55, 244, 255, 0.028) 0 1px, transparent 1px 34px);
  mask-image: radial-gradient(ellipse at center, black 30%, transparent 85%);
}
.board::after {
  content: "";
  position: absolute;
  inset: 5px;
  pointer-events: none;
  border: 1px solid rgba(112, 196, 255, 0.12);
  border-radius: 11px;
}

.zone-row {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 5px;
  min-height: 0;
}
.zone-row.foe-back { opacity: 0.92; }

.zone {
  position: relative;
  min-width: 0;
  min-height: 0;
  border: 1px solid rgba(112, 196, 255, 0.11);
  border-radius: 7px;
  background:
    radial-gradient(ellipse at 50% 40%, rgba(112, 196, 255, 0.035), transparent 66%),
    repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.012) 0 1px, transparent 1px 7px);
  transition: border-color 0.2s, background 0.2s, box-shadow 0.2s;
  overflow: visible;
}
.zone::before {
  content: "";
  position: absolute;
  inset: 3px;
  border: 1px solid rgba(112, 196, 255, 0.055);
  border-radius: 4px;
  pointer-events: none;
  transition: border-color 0.2s;
}
.zone::after {
  content: attr(data-index);
  position: absolute;
  right: 4px;
  bottom: 2px;
  font-family: var(--font-ui);
  font-size: 6px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: rgba(112, 196, 255, 0.22);
  pointer-events: none;
}
.zone.foe-front { border-color: rgba(255, 46, 138, 0.12); }
.zone.foe-back { border-color: rgba(255, 46, 138, 0.09); }
.zone:hover { border-color: rgba(112, 220, 255, 0.38); }
.zone.valid {
  cursor: pointer;
  border-color: rgba(55, 244, 255, 0.75);
  background:
    radial-gradient(ellipse at center, rgba(55, 244, 255, 0.2), transparent 70%),
    rgba(55, 244, 255, 0.05);
  box-shadow: 0 0 18px rgba(55, 244, 255, 0.28), inset 0 0 18px rgba(55, 244, 255, 0.12);
  animation: validPulse 1.5s ease-in-out infinite;
}
.zone.valid::before { border-color: rgba(55, 244, 255, 0.4); }
.zone.valid .zone-plus { opacity: 1; transform: scale(1); }
.zone-plus {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: var(--cyan-soft);
  font-family: var(--font-ui);
  font-size: 20px;
  font-weight: 300;
  opacity: 0;
  transform: scale(0.6);
  transition: opacity 0.2s, transform 0.2s;
  text-shadow: 0 0 14px var(--cyan);
  pointer-events: none;
}
.zone.targetable {
  cursor: crosshair;
  border-color: rgba(255, 46, 138, 0.9);
  box-shadow: 0 0 20px rgba(255, 46, 138, 0.42), inset 0 0 20px rgba(255, 46, 138, 0.16);
  animation: targetPulse 1.1s ease-in-out infinite;
}
.zone.targetable::before { border-color: rgba(255, 46, 138, 0.35); }
.zone.selected-source {
  border-color: rgba(255, 209, 102, 0.9);
  box-shadow: 0 0 22px rgba(255, 209, 102, 0.4), inset 0 0 18px rgba(255, 209, 102, 0.12);
}
.zone.fx-hit { animation: zoneHit 0.42s ease; }
.zone.flash::before { animation: zoneFlash 0.6s ease; }

.board-center {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 0;
  padding: 0 8px;
  pointer-events: none;
}
.center-line {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(55, 244, 255, 0.3), transparent);
}
.vs-mark {
  position: relative;
  flex: none;
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-family: var(--font-ui);
  font-size: 15px;
  font-weight: 900;
  letter-spacing: -0.04em;
  color: var(--text);
  text-shadow: 0 0 20px rgba(55, 244, 255, 0.5);
}
.vs-mark span {
  font-size: 6px;
  font-weight: 800;
  letter-spacing: 0.24em;
  color: var(--muted-2);
  text-shadow: none;
}
.phase-chip {
  flex: none;
  padding: 2px 8px;
  border: 1px solid rgba(55, 244, 255, 0.3);
  border-radius: 999px;
  background: rgba(55, 244, 255, 0.08);
  color: var(--cyan-soft);
  font-family: var(--font-ui);
  font-size: 7.5px;
  font-weight: 900;
  letter-spacing: 0.14em;
  white-space: nowrap;
  box-shadow: 0 0 14px rgba(55, 244, 255, 0.12);
}
.phase-chip.foe {
  border-color: rgba(255, 46, 138, 0.35);
  background: rgba(255, 46, 138, 0.08);
  color: var(--magenta-soft);
  box-shadow: 0 0 14px rgba(255, 46, 138, 0.12);
}
.phase-chip.busy { animation: chipBlink 1s ease-in-out infinite; }

.rail {
  position: relative;
  z-index: 2;
  flex: none;
  width: 26px;
  height: 72%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-ui);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.26em;
  color: rgba(112, 196, 255, 0.35);
  writing-mode: vertical-rl;
  text-orientation: mixed;
  pointer-events: none;
}
.rail b {
  font-size: 12px;
  letter-spacing: 0.06em;
  color: rgba(55, 244, 255, 0.6);
  text-shadow: 0 0 12px rgba(55, 244, 255, 0.35);
}
.rail-line { width: 1px; flex: 1; max-height: 90px; background: linear-gradient(180deg, transparent, rgba(55, 244, 255, 0.35), transparent); }

/* ------------------------------------------------------------------ cards */

.card {
  --el-a: #37f4ff;
  --el-b: #9bfbff;
  --rarity: rgba(112, 196, 255, 0.5);
  position: absolute;
  inset: 2px;
  display: block;
  border: 1px solid color-mix(in srgb, var(--el-a) 52%, transparent);
  border-radius: 6px;
  background: linear-gradient(165deg, #0b1226, #050811 70%);
  box-shadow:
    0 4px 14px rgba(0, 0, 0, 0.55),
    inset 0 0 18px rgba(0, 0, 0, 0.55),
    0 0 12px color-mix(in srgb, var(--el-a) 18%, transparent);
  overflow: hidden;
  transform-origin: 50% 80%;
  transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
}
.card::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 5;
  border: 1px solid color-mix(in srgb, var(--rarity) 70%, transparent);
  border-radius: inherit;
  pointer-events: none;
  opacity: 0.55;
}
.card.rarity-SR { --rarity: #c58cff; }
.card.rarity-UR { --rarity: #ffd166; }
.card.rarity-UR::before { opacity: 0.9; box-shadow: inset 0 0 14px rgba(255, 209, 102, 0.22); }

.card-inner {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 3px;
  animation: idleFloat var(--float-dur, 4.4s) ease-in-out infinite;
  animation-delay: var(--float-delay, 0s);
  will-change: transform;
}
.card-holo {
  position: absolute;
  inset: 0;
  z-index: 4;
  background: linear-gradient(112deg, transparent 32%, rgba(255, 255, 255, 0.32) 45%, rgba(255, 255, 255, 0.04) 55%, transparent 68%);
  background-size: 260% 260%;
  mix-blend-mode: screen;
  opacity: 0.42;
  animation: holoSweep 5.2s linear infinite;
  pointer-events: none;
}
.card-art {
  position: relative;
  flex: 1;
  min-height: 0;
  display: grid;
  place-items: center;
  margin: 2px 0;
  border-radius: 4px;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 42%, color-mix(in srgb, var(--el-a) 42%, transparent), transparent 63%),
    radial-gradient(circle at 50% 110%, color-mix(in srgb, var(--el-b) 18%, transparent), transparent 56%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), transparent 42%, rgba(0, 0, 0, 0.4));
  box-shadow: inset 0 0 12px rgba(0, 0, 0, 0.5);
}
.card-art::before {
  content: "";
  position: absolute;
  width: 76%;
  aspect-ratio: 1;
  border: 1px solid color-mix(in srgb, var(--el-a) 36%, transparent);
  border-radius: 50%;
  box-shadow: inset 0 0 18px color-mix(in srgb, var(--el-a) 12%, transparent);
  animation: sigilSpin 18s linear infinite;
}
.card-art::after {
  content: "";
  position: absolute;
  width: 54%;
  aspect-ratio: 1;
  border: 1px dashed color-mix(in srgb, var(--el-b) 40%, transparent);
  transform: rotate(45deg);
  animation: sigilSpin 26s linear infinite reverse;
}
.card-glyph {
  position: relative;
  z-index: 2;
  font-family: var(--font-jp);
  font-size: clamp(21px, 2.6vw, 38px);
  font-weight: 900;
  line-height: 1;
  color: var(--el-b);
  text-shadow:
    0 0 8px color-mix(in srgb, var(--el-a) 90%, transparent),
    0 0 24px color-mix(in srgb, var(--el-a) 60%, transparent),
    0 2px 0 rgba(0, 0, 0, 0.6);
}
.card-glyph::before {
  content: "";
  position: absolute;
  inset: -28%;
  z-index: -1;
  background: radial-gradient(circle, color-mix(in srgb, var(--el-a) 38%, transparent), transparent 65%);
  animation: glyphPulse 3s ease-in-out infinite;
}
.card-art .art-index {
  position: absolute;
  left: 3px;
  bottom: 1px;
  z-index: 2;
  font-family: var(--font-ui);
  font-size: 5px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: rgba(255, 255, 255, 0.3);
}
.card-head {
  position: absolute;
  top: 3px;
  left: 3px;
  right: 3px;
  z-index: 6;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  pointer-events: none;
}
.card-cost {
  display: grid;
  place-items: center;
  width: clamp(14px, 1.6vw, 20px);
  height: clamp(14px, 1.6vw, 20px);
  border: 1px solid color-mix(in srgb, var(--el-a) 68%, transparent);
  border-radius: 50%;
  background: rgba(3, 7, 16, 0.86);
  color: var(--el-b);
  font-family: var(--font-mono);
  font-size: clamp(7px, 0.72vw, 10px);
  font-weight: 700;
  box-shadow: 0 0 8px color-mix(in srgb, var(--el-a) 35%, transparent);
}
.card-type {
  padding: 1px 3px;
  border-radius: 2px;
  background: rgba(3, 7, 16, 0.72);
  border: 1px solid color-mix(in srgb, var(--el-a) 30%, transparent);
  color: color-mix(in srgb, var(--el-b) 85%, white);
  font-family: var(--font-ui);
  font-size: clamp(4.5px, 0.42vw, 6px);
  font-weight: 900;
  letter-spacing: 0.1em;
}
.card.type-trap .card-type { color: var(--magenta-soft); border-color: rgba(255, 46, 138, 0.35); }
.card-name {
  position: relative;
  z-index: 6;
  flex: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 0 1px;
  font-family: var(--font-jp);
  font-size: clamp(6px, 0.68vw, 9.5px);
  font-weight: 700;
  line-height: 1.35;
  color: #f2f8ff;
  text-shadow: 0 1px 3px #000;
}
.card-name small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: var(--font-ui);
  font-size: clamp(3.5px, 0.34vw, 5px);
  font-weight: 700;
  letter-spacing: 0.08em;
  color: rgba(159, 188, 220, 0.66);
}
.card-stats {
  position: relative;
  z-index: 6;
  flex: none;
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 1px 1px 0;
  font-family: var(--font-ui);
  font-size: clamp(4.5px, 0.46vw, 6.5px);
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--muted);
  white-space: nowrap;
}
.card-stats .atk { color: #ffcf7a; }
.card-stats .def { color: #9fd4ff; }
.card-stats b { font-family: var(--font-mono); font-size: clamp(5.5px, 0.56vw, 8px); font-weight: 700; }
.card-stats .sep { color: rgba(112, 196, 255, 0.25); }
.card-desc {
  display: none;
  flex: none;
  padding: 2px 1px 0;
  font-size: 7px;
  line-height: 1.45;
  color: rgba(190, 210, 235, 0.72);
}
.card.hand-card .card-desc { display: block; }

.card.face-down {
  border-color: rgba(55, 244, 255, 0.3);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.55), 0 0 12px rgba(55, 244, 255, 0.12);
}
.card.face-down .card-inner { animation: none; }
.card-back {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background:
    repeating-linear-gradient(45deg, rgba(55, 244, 255, 0.06) 0 1px, transparent 1px 6px),
    repeating-linear-gradient(-45deg, rgba(63, 140, 255, 0.05) 0 1px, transparent 1px 6px),
    radial-gradient(circle at 50% 50%, rgba(55, 244, 255, 0.18), transparent 62%),
    linear-gradient(160deg, #081226, #04070f);
  overflow: hidden;
}
.card-back::before {
  content: "";
  position: absolute;
  width: 55%;
  aspect-ratio: 1;
  border: 1px solid rgba(55, 244, 255, 0.45);
  border-radius: 50%;
  box-shadow: 0 0 14px rgba(55, 244, 255, 0.25), inset 0 0 14px rgba(55, 244, 255, 0.15);
  animation: sigilSpin 14s linear infinite;
}
.card-back::after {
  content: "24";
  position: relative;
  z-index: 2;
  font-family: var(--font-ui);
  font-size: clamp(13px, 1.7vw, 23px);
  font-weight: 900;
  letter-spacing: -0.06em;
  color: rgba(154, 251, 255, 0.9);
  text-shadow: 0 0 16px rgba(55, 244, 255, 0.8);
}
.card-back .back-hex {
  position: absolute;
  inset: 12%;
  border: 1px solid rgba(55, 244, 255, 0.18);
  clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%);
}

.card.exhausted { filter: grayscale(0.65) brightness(0.62); }
.card.exhausted::after {
  content: "USED";
  position: absolute;
  z-index: 8;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%) rotate(-14deg);
  padding: 1px 4px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  background: rgba(0, 0, 0, 0.6);
  font-family: var(--font-ui);
  font-size: 5px;
  font-weight: 900;
  letter-spacing: 0.2em;
  color: rgba(255, 255, 255, 0.65);
}
.card.attacker-selected {
  filter: brightness(1.22);
  box-shadow: 0 0 22px rgba(255, 209, 102, 0.55), inset 0 0 16px rgba(255, 209, 102, 0.18);
  border-color: var(--gold);
}

/* hand */

.hand-area {
  position: relative;
  z-index: 4;
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 138px;
  padding-bottom: env(safe-area-inset-bottom);
}
.hand-wrap { min-width: 0; max-width: 100%; display: flex; justify-content: center; }
.hand {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  height: 134px;
  padding: 0 6px;
}
.hand:empty::after {
  content: "手札は空です";
  align-self: center;
  font-size: 10px;
  color: var(--muted-2);
}

.hand-card {
  position: relative;
  flex: none;
  width: clamp(66px, 6.2vw, 92px);
  aspect-ratio: 0.7;
  margin-left: -30px;
  border: 0;
  padding: 0;
  background: transparent;
  transform: rotate(var(--rot, 0deg)) translateY(var(--dy, 0px));
  transform-origin: 50% 100%;
  transition: transform 0.24s cubic-bezier(0.2, 0.8, 0.2, 1), filter 0.2s, z-index 0s;
  z-index: calc(10 + var(--i, 0));
  animation: handIn 0.4s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  animation-delay: calc(var(--i, 0) * 0.03s);
}
.hand-card:first-child { margin-left: 0; }
.hand-card:hover, .hand-card:focus-visible {
  transform: rotate(0deg) translateY(-18px) scale(1.07);
  z-index: 99;
}
.hand-card .card { inset: 0; }
.hand-card .card-inner { animation-duration: 3.8s; }
.hand-card .card-desc {
  display: block;
  overflow: hidden;
  height: 22px;
  font-size: clamp(4.5px, 0.42vw, 6.5px);
  line-height: 1.35;
  color: rgba(190, 210, 235, 0.68);
}
.hand-card.selected {
  transform: rotate(0deg) translateY(-26px) scale(1.1);
  z-index: 120;
  filter: drop-shadow(0 0 18px rgba(55, 244, 255, 0.75));
}
.hand-card.selected .card { border-color: var(--cyan); box-shadow: 0 0 30px rgba(55, 244, 255, 0.5), inset 0 0 20px rgba(55, 244, 255, 0.15); }
.hand-card.unaffordable { filter: saturate(0.35) brightness(0.58); }
.hand-card.unaffordable:hover { transform: rotate(0deg) translateY(-8px) scale(1.02); }
.hand-card.casting { animation: cardCast 0.45s ease forwards; }

.pile {
  position: relative;
  flex: none;
  width: 58px;
  height: 80px;
  border: 1px solid rgba(112, 196, 255, 0.2);
  border-radius: 7px;
  background: rgba(5, 9, 20, 0.72);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  padding-bottom: 4px;
  overflow: hidden;
  transition: border-color 0.2s, transform 0.2s;
}
.pile:hover { border-color: rgba(55, 244, 255, 0.5); transform: translateY(-2px); }
.pile-card {
  position: absolute;
  inset: 5px 7px 17px;
  border: 1px solid rgba(55, 244, 255, 0.22);
  border-radius: 4px;
  background:
    repeating-linear-gradient(45deg, rgba(55, 244, 255, 0.06) 0 1px, transparent 1px 5px),
    linear-gradient(160deg, #0a1730, #04070f);
  box-shadow: 0 0 10px rgba(55, 244, 255, 0.08);
}
.pile-card:nth-child(2) { transform: translate(2px, -2px); opacity: 0.55; }
.pile-label {
  position: relative;
  z-index: 2;
  font-family: var(--font-ui);
  font-size: 6px;
  font-weight: 900;
  letter-spacing: 0.2em;
  color: var(--muted-2);
}
.pile b {
  position: relative;
  z-index: 2;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--cyan-soft);
  text-shadow: 0 0 10px rgba(55, 244, 255, 0.4);
}
.grave-pile b { color: var(--magenta-soft); text-shadow: 0 0 10px rgba(255, 46, 138, 0.4); }
.pile.pulse { animation: pilePulse 0.4s ease; }

/* ------------------------------------------------------------------ log */

.log-panel { overflow: hidden; }
.turn-badge {
  padding: 3px 7px;
  border: 1px solid rgba(55, 244, 255, 0.24);
  border-radius: 5px;
  background: rgba(55, 244, 255, 0.06);
  color: var(--cyan-soft);
  font-family: var(--font-ui);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.12em;
}
.log {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 8px 10px 10px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  scrollbar-width: thin;
  scrollbar-color: rgba(55, 244, 255, 0.22) transparent;
}
.log::-webkit-scrollbar { width: 3px; }
.log::-webkit-scrollbar-thumb { background: rgba(55, 244, 255, 0.22); }
.log-line {
  flex: none;
  padding: 5px 7px;
  border-left: 2px solid rgba(112, 196, 255, 0.22);
  border-radius: 0 4px 4px 0;
  background: linear-gradient(90deg, rgba(112, 196, 255, 0.05), transparent 78%);
  font-size: 9px;
  line-height: 1.55;
  color: rgba(205, 220, 240, 0.82);
  animation: logIn 0.26s ease both;
}
.log-line b { color: var(--text); font-weight: 700; }
.log-line .who-p { color: var(--cyan); font-weight: 700; }
.log-line .who-c { color: var(--magenta-soft); font-weight: 700; }
.log-line .num { font-family: var(--font-mono); color: var(--gold); }
.log-line.p { border-left-color: rgba(55, 244, 255, 0.55); background: linear-gradient(90deg, rgba(55, 244, 255, 0.08), transparent 78%); }
.log-line.c { border-left-color: rgba(255, 46, 138, 0.55); background: linear-gradient(90deg, rgba(255, 46, 138, 0.08), transparent 78%); }
.log-line.sys { border-left-color: rgba(255, 209, 102, 0.55); background: linear-gradient(90deg, rgba(255, 209, 102, 0.07), transparent 78%); color: var(--gold); }
.log-line.big { font-size: 10px; }
.log-empty { margin: auto; text-align: center; font-size: 9px; line-height: 1.7; color: var(--muted-2); }

.turn-controls {
  flex: none;
  padding: 10px 12px 12px;
  border-top: 1px solid rgba(112, 196, 255, 0.1);
  background: linear-gradient(180deg, transparent, rgba(4, 7, 16, 0.5));
}
.phase-line {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-ui);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.16em;
  color: var(--cyan-soft);
}
.phase-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); animation: pulseDot 1.6s ease-in-out infinite; }
.phase-line.foe { color: var(--magenta-soft); }
.phase-line.foe .phase-dot { background: var(--magenta); box-shadow: 0 0 8px var(--magenta); }
.hint-line {
  min-height: 26px;
  margin-top: 5px;
  font-size: 8.5px;
  line-height: 1.5;
  color: var(--muted-2);
}
.end-turn {
  position: relative;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 42px;
  margin-top: 7px;
  border: 1px solid rgba(55, 244, 255, 0.55);
  border-radius: 8px;
  background:
    linear-gradient(110deg, rgba(55, 244, 255, 0.22), rgba(63, 140, 255, 0.14) 55%, rgba(255, 46, 138, 0.14));
  color: var(--cyan-soft);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  overflow: hidden;
  transition: transform 0.18s, box-shadow 0.18s, background 0.18s;
  box-shadow: 0 0 22px rgba(55, 244, 255, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.1);
}
.end-turn::before {
  content: "";
  position: absolute;
  top: 0;
  left: -70%;
  width: 40%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.35), transparent);
  transform: skewX(-18deg);
  animation: btnSweep 3.6s ease-in-out infinite;
}
.end-turn svg { width: 14px; height: 14px; fill: currentColor; }
.end-turn:hover:not(:disabled) { transform: translateY(-1px); box-shadow: 0 0 34px rgba(55, 244, 255, 0.3); background: linear-gradient(110deg, rgba(55, 244, 255, 0.36), rgba(63, 140, 255, 0.24) 55%, rgba(255, 46, 138, 0.2)); }
.end-turn:disabled { opacity: 0.32; cursor: not-allowed; filter: saturate(0.4); }
.end-turn.foe-turn { border-color: rgba(255, 46, 138, 0.28); color: var(--magenta-soft); background: rgba(255, 46, 138, 0.06); }

/* ------------------------------------------------------------------ FX */

.banner {
  position: fixed;
  left: 50%;
  top: 42%;
  z-index: 90;
  transform: translate(-50%, -50%);
  pointer-events: none;
  text-align: center;
  opacity: 0;
  white-space: nowrap;
}
.banner.show { animation: bannerIn 1.45s cubic-bezier(0.16, 0.8, 0.3, 1) both; }
.banner .banner-main {
  display: block;
  font-family: var(--font-ui);
  font-size: clamp(30px, 6vw, 70px);
  font-weight: 900;
  font-style: italic;
  letter-spacing: 0.06em;
  line-height: 1;
  color: transparent;
  background: linear-gradient(90deg, var(--cyan), #fff 45%, var(--cyan-soft));
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 22px rgba(55, 244, 255, 0.65));
}
.banner.foe .banner-main { background: linear-gradient(90deg, var(--magenta), #fff 45%, var(--magenta-soft)); -webkit-background-clip: text; background-clip: text; filter: drop-shadow(0 0 22px rgba(255, 46, 138, 0.65)); }
.banner .banner-sub {
  display: block;
  margin-top: 4px;
  font-family: var(--font-ui);
  font-size: clamp(7px, 0.9vw, 11px);
  font-weight: 800;
  letter-spacing: 0.5em;
  color: rgba(230, 246, 255, 0.7);
}
.banner::before, .banner::after {
  content: "";
  position: absolute;
  top: 50%;
  width: min(28vw, 300px);
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--cyan));
  opacity: 0.7;
}
.banner::before { right: calc(100% + 14px); }
.banner::after { left: calc(100% + 14px); transform: scaleX(-1); }
.banner.foe::before, .banner.foe::after { background: linear-gradient(90deg, transparent, var(--magenta)); }

.toast-stack {
  position: fixed;
  right: 18px;
  top: calc(var(--header-h) + 14px);
  z-index: 120;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 310px;
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 9px 12px;
  border: 1px solid rgba(55, 244, 255, 0.32);
  border-radius: 8px;
  background: linear-gradient(160deg, rgba(11, 24, 45, 0.97), rgba(5, 10, 22, 0.97));
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.5), 0 0 20px rgba(55, 244, 255, 0.08);
  font-size: 10px;
  line-height: 1.5;
  color: var(--text);
  animation: toastIn 0.32s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  pointer-events: auto;
}
.toast::before {
  content: "";
  flex: none;
  width: 5px;
  height: 5px;
  margin-top: 4px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
}
.toast.error { border-color: rgba(255, 46, 138, 0.45); }
.toast.error::before { background: var(--magenta); box-shadow: 0 0 8px var(--magenta); }
.toast.join { border-color: rgba(77, 255, 184, 0.4); }
.toast.join::before { background: var(--green); box-shadow: 0 0 8px var(--green); }
.toast.out { animation: toastOut 0.28s ease forwards; }

.fx-layer { position: fixed; inset: 0; z-index: 80; pointer-events: none; overflow: hidden; }
.fx {
  position: fixed;
  pointer-events: none;
  will-change: transform, opacity;
}
.fx-slash {
  height: 3px;
  transform-origin: 0 50%;
  background: linear-gradient(90deg, transparent, #fff, var(--cyan), transparent);
  box-shadow: 0 0 16px var(--cyan), 0 0 34px var(--cyan);
  animation: slash 0.32s cubic-bezier(0.1, 0.8, 0.3, 1) forwards;
}
.fx-slash.foe { background: linear-gradient(90deg, transparent, #fff, var(--magenta), transparent); box-shadow: 0 0 16px var(--magenta), 0 0 34px var(--magenta); }
.fx-beam {
  height: 2px;
  transform-origin: 0 50%;
  background: linear-gradient(90deg, transparent, var(--cyan), #fff);
  box-shadow: 0 0 18px var(--cyan);
  animation: beam 0.45s ease-out forwards;
}
.fx-beam.foe { background: linear-gradient(90deg, transparent, var(--magenta), #fff); box-shadow: 0 0 18px var(--magenta); }
.fx-ring {
  width: 26px;
  height: 26px;
  margin: -13px 0 0 -13px;
  border: 2px solid var(--cyan);
  border-radius: 50%;
  box-shadow: 0 0 20px var(--cyan), inset 0 0 12px var(--cyan);
  animation: ringBurst 0.62s ease-out forwards;
}
.fx-ring.foe { border-color: var(--magenta); box-shadow: 0 0 20px var(--magenta), inset 0 0 12px var(--magenta); }
.fx-ring.gold { border-color: var(--gold); box-shadow: 0 0 22px var(--gold), inset 0 0 12px var(--gold); }
.fx-dmg {
  font-family: var(--font-ui);
  font-size: clamp(18px, 2.4vw, 32px);
  font-weight: 900;
  font-style: italic;
  letter-spacing: -0.02em;
  color: #fff;
  text-shadow: 0 0 10px var(--magenta), 0 0 24px var(--magenta), 0 2px 2px #000;
  animation: dmgFloat 1s cubic-bezier(0.1, 0.8, 0.2, 1) forwards;
}
.fx-dmg.heal { color: #d9ffe9; text-shadow: 0 0 10px var(--green), 0 0 24px var(--green), 0 2px 2px #000; }
.fx-dmg.gold { color: #fff5cf; text-shadow: 0 0 10px var(--gold), 0 0 24px var(--gold), 0 2px 2px #000; }
.fx-spark {
  width: 4px;
  height: 4px;
  margin: -2px 0 0 -2px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
  animation: sparkFly 0.7s ease-out forwards;
}
.fx-spark.foe { background: var(--magenta); box-shadow: 0 0 8px var(--magenta); }
.fx-spark.gold { background: var(--gold); box-shadow: 0 0 8px var(--gold); }
.fx-ghost {
  position: fixed;
  z-index: 85;
  border-radius: 6px;
  opacity: 0.95;
  filter: drop-shadow(0 0 18px rgba(55, 244, 255, 0.8));
  pointer-events: none;
}
.fx-ghost .card { inset: 0; }
.fx-ghost.foe { filter: drop-shadow(0 0 18px rgba(255, 46, 138, 0.8)); }

.damage-flash {
  position: fixed;
  inset: 0;
  z-index: 70;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(255, 20, 70, 0.32) 100%);
  animation: damageFlash 0.5s ease-out forwards;
}
.heal-flash {
  position: fixed;
  inset: 0;
  z-index: 70;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(40, 255, 160, 0.18) 100%);
  animation: damageFlash 0.6s ease-out forwards;
}

.arena-shell.shake { animation: shake 0.42s cubic-bezier(0.36, 0.07, 0.19, 0.97); }

/* ------------------------------------------------------------------ modal */

.modal {
  position: fixed;
  inset: 0;
  z-index: 150;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(2, 4, 10, 0.72);
  backdrop-filter: blur(10px);
}
.modal[hidden] { display: none; }
.modal-card {
  position: relative;
  width: min(100%, 720px);
  max-height: min(88dvh, 800px);
  overflow-y: auto;
  padding: 30px 30px 26px;
  border: 1px solid rgba(112, 196, 255, 0.28);
  border-radius: 16px;
  background:
    linear-gradient(155deg, rgba(27, 45, 88, 0.5), transparent 45%),
    linear-gradient(180deg, rgba(10, 17, 36, 0.98), rgba(4, 7, 16, 0.98));
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.7), 0 0 60px rgba(55, 244, 255, 0.08);
  animation: modalIn 0.35s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  scrollbar-width: thin;
}
.modal-close {
  position: absolute;
  top: 12px;
  right: 14px;
  width: 32px;
  height: 32px;
  border: 1px solid rgba(112, 196, 255, 0.2);
  border-radius: 8px;
  background: rgba(5, 9, 20, 0.7);
  color: var(--muted);
  font-size: 18px;
  line-height: 1;
}
.modal-close:hover { color: var(--cyan); border-color: rgba(55, 244, 255, 0.5); }
.modal-kicker {
  font-family: var(--font-ui);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.34em;
  color: var(--cyan);
}
.modal-card h2 {
  margin: 7px 0 20px;
  font-size: clamp(24px, 3.4vw, 42px);
  font-weight: 900;
  letter-spacing: 0.04em;
  line-height: 1.1;
}
.rules-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 18px; }
.rule { position: relative; padding: 12px 12px 12px 14px; border: 1px solid rgba(112, 196, 255, 0.1); border-radius: 9px; background: rgba(8, 14, 29, 0.55); }
.rule-no { position: absolute; top: 10px; right: 11px; font-family: var(--font-ui); font-size: 9px; font-weight: 900; letter-spacing: 0.1em; color: rgba(112, 196, 255, 0.28); }
.rule h3 { margin: 0 0 5px; font-size: 12px; color: var(--cyan-soft); }
.rule p { margin: 0; font-size: 10px; line-height: 1.65; color: var(--muted); }
.rules-note {
  margin: 18px 0;
  padding: 12px 14px;
  border-left: 2px solid var(--gold);
  background: linear-gradient(90deg, rgba(255, 209, 102, 0.07), transparent);
  font-size: 10px;
  line-height: 1.7;
  color: var(--muted);
}
.rules-note b { color: var(--gold); }
.btn-primary.wide { width: 100%; padding: 11px; font-size: 12px; }

.result-modal { background: rgba(2, 4, 10, 0.8); }
.result-card {
  width: min(100%, 600px);
  text-align: center;
  overflow: hidden;
  padding: 44px 34px 32px;
}
.result-card::before {
  content: "";
  position: absolute;
  inset: -40% -20% auto;
  height: 90%;
  background: radial-gradient(ellipse at center, rgba(55, 244, 255, 0.2), transparent 65%);
  pointer-events: none;
}
.result-card.lose::before { background: radial-gradient(ellipse at center, rgba(255, 46, 138, 0.2), transparent 65%); }
.result-rays {
  position: absolute;
  left: 50%;
  top: 30%;
  width: 150%;
  aspect-ratio: 1;
  transform: translate(-50%, -50%);
  background: repeating-conic-gradient(from 0deg, rgba(55, 244, 255, 0.11) 0deg 2deg, transparent 2deg 12deg);
  animation: sigilSpin 40s linear infinite;
  mask-image: radial-gradient(circle, black 0 18%, transparent 55%);
  pointer-events: none;
}
.result-card.lose .result-rays { background: repeating-conic-gradient(from 0deg, rgba(255, 46, 138, 0.11) 0deg 2deg, transparent 2deg 12deg); }
.result-card h2 {
  position: relative;
  margin: 4px 0 2px;
  font-family: var(--font-ui);
  font-size: clamp(52px, 8vw, 92px);
  font-style: italic;
  letter-spacing: 0.02em;
  line-height: 0.95;
  color: transparent;
  background: linear-gradient(180deg, #fff, var(--cyan) 55%, #0aa8c9);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 28px rgba(55, 244, 255, 0.55));
  animation: resultPop 0.6s cubic-bezier(0.2, 0.9, 0.2, 1.2) both;
}
.result-card.lose h2 { background: linear-gradient(180deg, #fff, var(--magenta) 55%, #a30049); -webkit-background-clip: text; background-clip: text; filter: drop-shadow(0 0 28px rgba(255, 46, 138, 0.55)); }
.result-lp { position: relative; display: inline-flex; align-items: baseline; gap: 8px; margin-top: 4px; font-family: var(--font-ui); font-size: 9px; font-weight: 800; letter-spacing: 0.2em; color: var(--muted-2); }
.result-lp b { font-family: var(--font-mono); font-size: 26px; letter-spacing: 0; color: var(--text); }
.result-stats { position: relative; display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 22px 0 24px; }
.result-stats div { padding: 10px 6px; border: 1px solid rgba(112, 196, 255, 0.12); border-radius: 8px; background: rgba(6, 11, 23, 0.6); }
.result-stats span { display: block; font-family: var(--font-ui); font-size: 7.5px; font-weight: 800; letter-spacing: 0.16em; color: var(--muted-2); }
.result-stats b { display: block; margin-top: 4px; font-family: var(--font-mono); font-size: 20px; color: var(--cyan-soft); }
.result-actions { position: relative; display: flex; gap: 9px; }
.result-actions .btn-primary { flex: 1.4; padding: 11px; font-size: 12px; }
.result-actions .btn-ghost { flex: 1; padding: 11px; font-size: 11px; }

.card-tooltip {
  position: fixed;
  z-index: 300;
  width: 218px;
  padding: 10px 11px;
  border: 1px solid rgba(112, 220, 255, 0.4);
  border-radius: 9px;
  background: linear-gradient(160deg, rgba(13, 25, 50, 0.98), rgba(4, 8, 18, 0.98));
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.65), 0 0 22px rgba(55, 244, 255, 0.08);
  pointer-events: none;
  animation: tooltipIn 0.15s ease both;
}
.card-tooltip[hidden] { display: none; }
.card-tooltip .tt-kicker { font-family: var(--font-ui); font-size: 7px; font-weight: 900; letter-spacing: 0.2em; color: var(--cyan); }
.card-tooltip .tt-name { margin-top: 3px; font-size: 12px; font-weight: 700; }
.card-tooltip .tt-name small { display: block; font-family: var(--font-ui); font-size: 6.5px; letter-spacing: 0.12em; color: var(--muted-2); }
.card-tooltip .tt-stats { display: flex; gap: 9px; margin: 7px 0; font-family: var(--font-mono); font-size: 9px; }
.card-tooltip .tt-stats .atk { color: var(--gold); }
.card-tooltip .tt-stats .def { color: #9fd4ff; }
.card-tooltip .tt-text { font-size: 9px; line-height: 1.6; color: var(--muted); }

.drawer-scrim {
  position: fixed;
  inset: 0;
  z-index: 45;
  background: rgba(2, 4, 10, 0.62);
  backdrop-filter: blur(3px);
}
.drawer-scrim[hidden] { display: none; }

/* ------------------------------------------------------------------ motion */

@keyframes nebulaDrift {
  0% { transform: translate3d(-2%, -1%, 0) scale(1); }
  100% { transform: translate3d(2%, 2%, 0) scale(1.06); }
}
@keyframes pulseRing {
  0% { transform: scale(0.7); opacity: 0.8; }
  100% { transform: scale(1.8); opacity: 0; }
}
@keyframes pulseDot { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
@keyframes ringSpin { to { transform: rotate(360deg); } }
@keyframes idleFloat {
  0%, 100% { transform: translate3d(0, 0, 0) rotate(0deg); }
  50% { transform: translate3d(0, -2.5px, 0) rotate(0.35deg); }
}
@keyframes holoSweep {
  0% { background-position: 180% 0; }
  100% { background-position: -120% 0; }
}
@keyframes sigilSpin { to { transform: rotate(360deg); } }
@keyframes glyphPulse { 0%, 100% { opacity: 0.7; transform: scale(0.94); } 50% { opacity: 1; transform: scale(1.06); } }
@keyframes selfSweep { 0%, 55% { left: -60%; } 100% { left: 150%; } }
@keyframes roomIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
@keyframes validPulse {
  0%, 100% { box-shadow: 0 0 14px rgba(55, 244, 255, 0.22), inset 0 0 14px rgba(55, 244, 255, 0.1); }
  50% { box-shadow: 0 0 30px rgba(55, 244, 255, 0.45), inset 0 0 24px rgba(55, 244, 255, 0.18); }
}
@keyframes targetPulse {
  0%, 100% { box-shadow: 0 0 14px rgba(255, 46, 138, 0.3), inset 0 0 14px rgba(255, 46, 138, 0.12); }
  50% { box-shadow: 0 0 30px rgba(255, 46, 138, 0.6), inset 0 0 24px rgba(255, 46, 138, 0.2); }
}
@keyframes lpHit { 0%, 100% { transform: none; } 30% { transform: translateX(-3px); color: #fff; } 60% { transform: translateX(2px); } }
@keyframes lowLp { 0%, 100% { opacity: 1; } 50% { opacity: 0.55; } }
@keyframes zoneHit { 0%, 100% { transform: none; } 25% { transform: translateX(-4px) rotate(-1deg); } 55% { transform: translateX(4px) rotate(1deg); } 80% { transform: translateX(-2px); } }
@keyframes zoneFlash { 0%, 100% { background: transparent; } 40% { background: rgba(255, 255, 255, 0.22); } }
@keyframes chipBlink { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }
@keyframes handIn { from { opacity: 0; transform: translateY(22px) scale(0.9); } to { opacity: 1; } }
@keyframes cardCast { to { opacity: 0; transform: translateY(-30px) scale(0.9); } }
@keyframes pilePulse { 0%, 100% { transform: none; } 50% { transform: translateY(-4px) scale(1.04); box-shadow: 0 0 22px rgba(55, 244, 255, 0.25); } }
@keyframes logIn { from { opacity: 0; transform: translateX(5px); } to { opacity: 1; transform: none; } }
@keyframes btnSweep { 0%, 62% { left: -70%; } 100% { left: 140%; } }
@keyframes bannerIn {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.82); letter-spacing: 0.2em; }
  18% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  78% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.04); }
}
@keyframes toastIn { from { opacity: 0; transform: translateX(20px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateX(20px); } }
@keyframes slash {
  0% { transform: scaleX(0) rotate(var(--angle, 0deg)); opacity: 0; }
  22% { opacity: 1; }
  100% { transform: scaleX(1) rotate(var(--angle, 0deg)); opacity: 0; }
}
@keyframes beam {
  0% { transform: scaleX(0) rotate(var(--angle, 0deg)); opacity: 0; }
  20% { opacity: 1; }
  100% { transform: scaleX(1) rotate(var(--angle, 0deg)); opacity: 0; }
}
@keyframes ringBurst {
  0% { transform: scale(0.25); opacity: 0.95; }
  100% { transform: scale(3.2); opacity: 0; }
}
@keyframes dmgFloat {
  0% { transform: translate(-50%, 0) scale(0.6); opacity: 0; }
  18% { transform: translate(-50%, -14px) scale(1.15); opacity: 1; }
  100% { transform: translate(-50%, -64px) scale(1); opacity: 0; }
}
@keyframes sparkFly {
  0% { transform: translate(0, 0) scale(1); opacity: 1; }
  100% { transform: translate(var(--dx, 20px), var(--dy, -30px)) scale(0); opacity: 0; }
}
@keyframes damageFlash { 0% { opacity: 0; } 16% { opacity: 1; } 100% { opacity: 0; } }
@keyframes shake {
  10%, 90% { transform: translate3d(-1px, 0, 0); }
  20%, 80% { transform: translate3d(2px, 0, 0); }
  30%, 50%, 70% { transform: translate3d(-4px, 0, 0); }
  40%, 60% { transform: translate3d(4px, 0, 0); }
}
@keyframes modalIn { from { opacity: 0; transform: translateY(14px) scale(0.98); } to { opacity: 1; transform: none; } }
@keyframes resultPop { 0% { opacity: 0; transform: scale(0.6); } 100% { opacity: 1; transform: scale(1); } }
@keyframes tooltipIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }

/* ------------------------------------------------------------------ responsive */

@media (max-width: 1360px) {
  .layout { grid-template-columns: 250px minmax(0, 1fr) 238px; }
  .room-pill { max-width: 360px; }
  .rail { display: none; }
}

@media (max-width: 1180px) {
  .layout { grid-template-columns: minmax(0, 1fr); padding: 10px 12px 12px; }
  .arena-shell { height: 100%; }
